const PATCHES=Object.freeze([{id:'sheep-west-meadow',kind:'sheep',x:-43,z:-39,phase:.2,range:2.1},{id:'sheep-north-meadow',kind:'sheep',x:43,z:45,phase:2.4,range:1.9},{id:'rabbit-west-meadow',kind:'rabbit',x:-44,z:34,phase:1.1,range:1.55},{id:'rabbit-east-meadow',kind:'rabbit',x:44,z:-40,phase:3.2,range:1.65}]);
export function faunaRoutine(seconds,phase,range,kind='sheep',hour=12){const resting=hour<5||hour>=21,pace=resting?.08:kind==='rabbit'?.42:.16,t=seconds*pace+phase,scale=resting?.13:1;return {offsetX:Math.sin(t)*range*scale,offsetZ:Math.sin(t*.73+phase)*range*.55*scale,heading:Math.atan2(Math.cos(t)*pace*range,Math.cos(t*.73+phase)*pace*range*.4),grazing:resting?.16:kind==='sheep'?.5+.5*Math.sin(t*1.65):.12+.12*Math.sin(t*2.1),hop:resting||kind!=='rabbit'?0:Math.pow(Math.max(0,Math.sin(t*2.65)),10)*.18,bodyBob:kind==='sheep'?Math.sin(t*2)*.018:0,resting,activity:resting?'Rest':kind==='sheep'?'Graze':'Forage'};}
function part(B,scene,name,mat,pos,scale,color){const m=B.MeshBuilder.CreateSphere(name,{diameter:1,segments:8},scene);m.material=mat;m.position.set(...pos);m.scaling.set(...scale);m.isPickable=false;const count=m.getTotalVertices(),c=B.Color3.FromHexString(color),colors=new Float32Array(count*4);for(let i=0;i<count;i++){colors[i*4]=c.r;colors[i*4+1]=c.g;colors[i*4+2]=c.b;colors[i*4+3]=1;}m.setVerticesData(B.VertexBuffer.ColorKind,colors,false,4);return m;}
function merge(B,parts,parent,name){const m=B.Mesh.MergeMeshes(parts,true,true,undefined,false,false);if(!m)throw Error('Fauna merge failed: '+name);m.name=name;m.parent=parent;m.isPickable=false;return m;}
export function createAmbientFauna(B,scene,{heightAt=(x,z)=>0,shadows=null,patches=PATCHES}={}){const mat=(n)=>{const m=new B.StandardMaterial(n,scene);m.diffuseColor=B.Color3.White();m.specularColor=new B.Color3(.025,.025,.025);m.useVertexColors=true;return m;},wool=mat('Sheep vertex-coloured fleece'),rabbit=mat('Rabbit vertex-coloured fur'),animals=[];
for(const p of patches){const root=new B.TransformNode(p.id,scene),parts=[],material=p.kind==='sheep'?wool:rabbit;const add=(name,pos,scale,color)=>parts.push(part(B,scene,p.id+' '+name,material,pos,scale,color));
if(p.kind==='sheep'){add('fleece', [0,.48,0],[.92,.58,.62],'#e7dfca');for(const [x,y,z] of [[-.34,.68,0],[-.12,.79,-.12],[.15,.78,-.1],[.36,.68,.02],[0,.72,.2]])add('wool curl',[x,y,z],[.34,.31,.34],'#e7dfca');add('tail',[-.5,.52,0],[.2,.2,.2],'#e7dfca');add('head',[.4,.58,0],[.27,.29,.25],'#51473d');add('muzzle',[.5,.51,-.14],[.16,.13,.15],'#51473d');add('ear-left',[.2,.67,0],[.13,.075,.08],'#51473d');add('ear-right',[.6,.67,0],[.13,.075,.08],'#51473d');for(const [x,z] of [[-.27,-.2],[-.27,.2],[.27,-.2],[.27,.2]]){const leg=B.MeshBuilder.CreateCylinder(p.id+' leg',{diameter:.075,height:.32,tessellation:6},scene);leg.material=material;leg.position.set(x,.16,z);leg.isPickable=false;const count=leg.getTotalVertices(),c=B.Color3.FromHexString('#51473d'),colors=new Float32Array(count*4);for(let i=0;i<count;i++){colors[i*4]=c.r;colors[i*4+1]=c.g;colors[i*4+2]=c.b;colors[i*4+3]=1;}leg.setVerticesData(B.VertexBuffer.ColorKind,colors,false,4);parts.push(leg);}}
else{add('body',[0,.34,0],[.48,.3,.34],'#96714d');add('tail',[-.31,.4,.02],[.15,.15,.15],'#d5c0a1');add('head',[.23,.55,0],[.24,.24,.22],'#96714d');add('muzzle',[.33,.48,-.12],[.12,.1,.12],'#c4a47c');add('ear-left',[.14,.8,0],[.085,.29,.07],'#96714d');add('ear-right',[.32,.8,0],[.085,.29,.07],'#96714d');for(const [x,z] of [[-.14,-.12],[-.14,.12],[.14,-.12],[.14,.12]]){const leg=B.MeshBuilder.CreateCylinder(p.id+' leg',{diameter:.065,height:.22,tessellation:6},scene);leg.material=material;leg.position.set(x,.11,z);leg.isPickable=false;const count=leg.getTotalVertices(),c=B.Color3.FromHexString('#6c503b'),colors=new Float32Array(count*4);for(let i=0;i<count;i++){colors[i*4]=c.r;colors[i*4+1]=c.g;colors[i*4+2]=c.b;colors[i*4+3]=1;}leg.setVerticesData(B.VertexBuffer.ColorKind,colors,false,4);parts.push(leg);}}
const mesh=merge(B,parts,root,p.id+' single-mesh animal');root.position.set(p.x,heightAt(p.x,p.z),p.z);shadows?.addShadowCaster(mesh);animals.push({...p,root,mesh,home:{x:p.x,z:p.z},activity:'Idle'});}
return {animals,dispose(){for(const a of animals)a.root.dispose(false,true);wool.dispose();rabbit.dispose();}};}
